'use strict';
const people=wiki.people, app=document.getElementById('app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number(n).toLocaleString('ko-KR');
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const write=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}};
let query='',category='전체',order='기본순',mapA=4,mapB=5,museumCategory='전체';
let saved=read('theme-wiki-saved',[]);if(!Array.isArray(saved))saved=[];
let museumSaved=read('tw-museum-saved',[]);if(!Array.isArray(museumSaved))museumSaved=[];
let profileEdits=read('tw-profiles',{});if(!profileEdits||typeof profileEdits!=='object'||Array.isArray(profileEdits))profileEdits={};
let trialHistory=read('tw-trials',[]);if(!Array.isArray(trialHistory))trialHistory=[];
let votes=read('tw-votes',{});if(!votes||typeof votes!=='object'||Array.isArray(votes))votes={};
const avatar=(p,cls='')=>`<span class="avatar ${cls}" role="img" aria-label="${esc(p.name)} 창작 아바타" style="background-position:${p.id%4*100/3}% ${Math.floor(p.id/4)*50}%"></span>`;
const tags=items=>items.map(t=>`<span class="tag">${esc(t)}</span>`).join('');
const link=p=>`<a class="wikilink" href="#person/${p.id}">${esc(p.name)}</a>`;
const options=id=>people.map(p=>`<option value="${p.id}" ${id===p.id?'selected':''}>${esc(p.name)}</option>`).join('');
const caseById=id=>wiki.cases.find(c=>c.id===id);
function toast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),2800)}
function age(p){const v=profileEdits[p.id]?.birthDate||p.birthDate;if(!v)return '미상';const b=new Date(v+'T00:00:00'),today=new Date();if(!Number.isFinite(b.getTime())||b>today)return '미상';let years=today.getFullYear()-b.getFullYear();if(today.getMonth()<b.getMonth()||today.getMonth()===b.getMonth()&&today.getDate()<b.getDate())years--;return `만 ${years}세`}
function similarity(a,b){const shared=a.tags.filter(t=>b.tags.includes(t));const related=a.relations.some(r=>r.person===b.id);return {score:shared.length*3+(related?1:0),shared,related}}
function similar(p){return people.filter(x=>x.id!==p.id).map(x=>({p:x,...similarity(p,x)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||a.p.id-b.p.id).slice(0,3)}
function personCard(p){return `<article class="person-card"><div class="card-top"><a href="#person/${p.id}" aria-label="${esc(p.name)} 문서">${avatar(p)}</a><button class="bookmark" data-save="${p.id}" aria-pressed="${saved.includes(p.id)}" aria-label="${esc(p.name)} 북마크">${saved.includes(p.id)?'★':'☆'}</button></div><a class="person-name" href="#person/${p.id}">${esc(p.name)} <span>↗</span></a><div class="nickname">${esc(p.user)}</div><p>${esc(p.line)}</p><div class="tags">${tags(p.tags)}</div><div class="card-bottom"><span>${esc(p.mbti.title)}</span><span>${age(p)}</span></div></article>`}
function home(){app.innerHTML=`<div class="breadcrumb">개테천위키 / 인물 문서</div><section class="welcome"><div class="eyebrow">THE PEOPLE ENCYCLOPEDIA</div><h1>친구인데,<br>아직 모르는 게 많다.</h1><p>이름부터 취향, 서로의 연결까지.<br>우리의 캐릭터를 한 문서씩 들여다보세요.</p><div class="welcome-label"><span class="live-dot"></span>12명의 인물 · 4개의 즐길 거리</div><div class="welcome-art" aria-hidden="true"><span class="orbit"></span>${[people[4],people[0],people[1]].map(p=>avatar(p)).join('')}<span class="art-note">각자의 캐릭터가 모이는 곳</span></div></section><section class="feature-links"><a href="#court"><span class="feature-icon">⚖</span><div><b>AI 재판소</b><small>그 사건, 판결을 내려보자</small></div><span>↗</span></a><a href="#museum"><span class="feature-icon amber">▣</span><div><b>흑역사 박물관</b><small>웃고 넘길 수 있는 장면들</small></div><span>↗</span></a><a href="#map"><span class="feature-icon violet">◎</span><div><b>인간관계 지도</b><small>우리 사이의 연결 찾기</small></div><span>↗</span></a></section><section class="directory"><div class="section-head"><div><span class="eyebrow">CHARACTER INDEX</span><h2>인물 문서 <span>12</span></h2></div><select id="sort" aria-label="인물 정렬">${['기본순','이름순','발언 많은 순'].map(t=>`<option ${order===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="directory-tools"><div class="chips">${['전체','야구','축구','게임','여행','음식','러닝','북마크'].map(t=>`<button data-filter="${t}" aria-pressed="${category===t}" class="chip ${category===t?'active':''}">${t}</button>`).join('')}</div><label class="search"><span>⌕</span><input id="search" type="search" value="${esc(query)}" placeholder="이름, MBTI, 취미 검색" aria-label="이름, MBTI, 취미 검색"></label></div><div id="result-count" class="count-note" aria-live="polite"></div><div id="cards" class="person-grid"></div></section><aside class="editor-note"><b>사람을 단정하는 대신, 캐릭터를 기록합니다.</b><span>확인되지 않은 나이는 미상으로, 달라지는 취향은 그때의 기록으로.</span><a href="#guide">편집 기준 읽기 →</a></aside>`;renderCards();document.getElementById('search').addEventListener('input',e=>{query=e.target.value;renderCards()});document.getElementById('sort').addEventListener('change',e=>{order=e.target.value;renderCards()})}
function searchText(p){return JSON.stringify([p.name,p.user,p.line,p.tags,p.mbti,p.likes,p.football,p.traits,p.relations.map(r=>r.text)]).toLowerCase()}
function renderCards(){const pattern={'야구':/야구|두산|KT/,'축구':/축구|아스날|리버풀|첼시/,'게임':/게임|메이플|로스트아크|오디세이|LoL|FC/,'여행':/여행|세종/,'음식':/음식|맥주|사케|닭발|고기|와인/,'러닝':/러닝/};let list=people.filter(p=>searchText(p).includes(query.trim().toLowerCase())&&(category==='전체'||category==='북마크'&&saved.includes(p.id)||pattern[category]?.test([p.tags.join(' '),p.likes.map(f=>f.title+' '+f.text).join(' ')].join(' '))));if(order==='이름순')list.sort((a,b)=>a.name.localeCompare(b.name,'ko'));if(order==='발언 많은 순')list.sort((a,b)=>b.count-a.count);document.getElementById('result-count').textContent=`${list.length}개의 인물 문서`;document.getElementById('cards').innerHTML=list.length?list.map(personCard).join(''):'<div class="empty">일치하는 인물이 없습니다. 검색어나 분류를 바꿔보세요.</div>'}
function person(id){const p=people[id];if(!p)return missing();const recommendations=similar(p),edit=profileEdits[p.id]||{};app.innerHTML=`<div class="breadcrumb"><a href="#">인물 문서</a> / ${esc(p.name)}</div><div class="document-title"><div><h1>${esc(p.name)}</h1><p>분류: <span class="wikilink">개별의테마천국 / 인물</span></p></div><button class="button" data-save="${id}" aria-pressed="${saved.includes(id)}">${saved.includes(id)?'★ 저장됨':'☆ 문서 저장'}</button></div><div class="wiki-document"><div class="document-body"><div class="toc"><b>목차</b>${['개요','취미와 취향','성향','비슷한 인물','인간관계','재판 기록'].map((t,i)=>`<a href="#person/${id}" data-section="section-${i}"><span>${i+1}.</span> ${t}</a>`).join('')}</div><section id="section-0" class="doc-section"><h2><span>1.</span> 개요</h2><p>${esc(p.line)}</p><p>개별의테마천국의 멤버. ${esc(p.tags.join(', '))} 이야기에 등장한다. 현재 문서는 ${p.first.slice(0,10)}부터 ${p.last.slice(0,10)}까지의 기록을 바탕으로 정리했다.</p></section><section id="section-1" class="doc-section"><h2><span>2.</span> 취미와 취향</h2>${p.likes.map(f=>`<div class="wiki-fact"><h3>${esc(f.title)}</h3><p>${esc(f.text)}</p></div>`).join('')}<div class="wiki-fact"><h3>축구 · 스포츠</h3><p>${esc(p.football.text)}</p></div></section><section id="section-2" class="doc-section"><h2><span>3.</span> 성향</h2><div class="trait-list">${p.traits.map((t,i)=>`<div><span>0${i+1}</span><b>${esc(t)}</b></div>`).join('')}</div><p class="muted">${esc(wiki.meta.note)}</p><h3>MBTI 기록</h3><p>${esc(p.mbti.text)}</p></section><section id="section-3" class="doc-section"><h2><span>4.</span> 비슷한 인물</h2><p class="muted">공통 취미 태그를 먼저 보고, 기록에 등장하는 관계를 보조로 반영합니다. 성격 궁합 점수가 아닙니다.</p><div class="similar-list">${recommendations.map(r=>`<a href="#person/${r.p.id}">${avatar(r.p)}<div><b>${esc(r.p.name)}</b><small>${r.shared.length?'공통 관심사 · '+esc(r.shared.join(', ')):'함께 등장하는 관계'}</small></div><span>↗</span></a>`).join('')||'<p>공통 태그를 확인한 인물이 없습니다.</p>'}</div></section><section id="section-4" class="doc-section"><h2><span>5.</span> 인간관계</h2>${p.relations.map(r=>`<div class="relation-row">${link(people[r.person])}<span>${esc(r.text)}</span></div>`).join('')}<a class="button" href="#map/${id}">관계 지도에서 보기 ↗</a></section><section id="section-5" class="doc-section"><h2><span>6.</span> 재판 기록</h2>${wiki.cases.filter(c=>c.defendant===id||c.related.includes(id)).map(c=>`<a class="case-link" href="#court/${c.id}"><span>${esc(c.category)}</span><b>${esc(c.title)}</b><span>→</span></a>`).join('')||'<p class="muted">등록된 모의 재판이 없습니다.</p>'}</section></div><aside class="infobox"><div class="infobox-name">${esc(p.name)}<small>${esc(p.user)}</small></div><div class="infobox-portrait">${avatar(p)}</div><dl><dt>이름</dt><dd>${esc(p.name)}</dd><dt>대화명</dt><dd>${esc(p.user)}</dd><dt>나이</dt><dd>${age(p)}${edit.birthDate?'<small>이 브라우저에서 입력</small>':''}</dd><dt>MBTI</dt><dd>${esc(p.mbti.title)}</dd><dt>취미</dt><dd>${esc(p.tags.join(' · '))}</dd><dt>성향</dt><dd>${esc(p.traits[0])}</dd><dt>비슷한 인물</dt><dd>${recommendations.map(r=>link(r.p)).join(' · ')||'미확인'}</dd><dt>기록된 발언</dt><dd>${num(p.count)}건</dd></dl><details class="profile-editor"><summary>생년월일 입력</summary><p>본인에게 확인한 정보만 입력하세요. 이 브라우저에만 저장됩니다.</p><form id="birth-form"><label for="birth-date">생년월일</label><input id="birth-date" type="date" min="1900-01-01" max="${new Date().toLocaleDateString('en-CA')}" value="${esc(edit.birthDate||'')}"><button class="button primary" type="submit">저장</button><button class="button" type="button" id="clear-birth">초기화</button></form></details></aside></div>`;document.getElementById('birth-form').addEventListener('submit',e=>{e.preventDefault();const birthDate=document.getElementById('birth-date').value;if(birthDate&&(birthDate<'1900-01-01'||new Date(birthDate)>new Date()))return toast('올바른 생년월일을 입력하세요.');profileEdits[id]={birthDate};const ok=write('tw-profiles',profileEdits);person(id);toast(ok?'이 브라우저에 저장했습니다.':'저장 공간을 사용할 수 없어 이번 화면에만 적용됩니다.')});document.getElementById('clear-birth').addEventListener('click',()=>{delete profileEdits[id];write('tw-profiles',profileEdits);person(id);toast('생년월일을 초기화했습니다.')})}
function court(id){const selected=caseById(id);app.innerHTML=`<div class="breadcrumb">개테천위키 / AI 재판소</div><section class="page-intro"><span class="eyebrow">THE FRIENDS COURT</span><h1>친구들 사이에도,<br>판결이 필요한 순간.</h1><p>판사는 진지하고, 사건은 사소하다.</p><span class="notice-pill">기록 기반 모의 판결 · 실시간 AI 연결 없음</span></section><div class="court-layout"><section class="panel court-form"><div class="panel-heading"><span>⚖</span><div><h2>사건 접수</h2><p>기록된 사건을 고르거나 새 사건을 접수하세요.</p></div></div><form id="trial-form"><label for="case-select">사건 유형</label><select id="case-select"><option value="">새 사건 접수</option>${wiki.cases.map(c=>`<option value="${c.id}" ${selected?.id===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select><label for="defendant">피고인</label><select id="defendant">${options(selected?.defendant??0)}</select><label for="charge">사건 내용</label><textarea id="charge" rows="3" required minlength="5" maxlength="600" placeholder="어떤 일이 있었나요? (5자 이상)">${esc(selected?.charge||'')}</textarea><label for="defense">피고인의 변론 <span class="optional">선택</span></label><textarea id="defense" rows="2" maxlength="600" placeholder="반대 의견이나 사정도 적어주세요."></textarea><fieldset><legend>판결 분위기</legend><label><input type="radio" name="tone" value="calm" checked> 차분한 재판장</label><label><input type="radio" name="tone" value="fun">장난스러운 재판장</label></fieldset><button type="submit" class="button primary wide">⚖ 개정하고 판결 보기</button><p class="muted form-note">친구끼리 즐기는 모의 재판입니다. 새 사건이나 변경된 주장은 사실을 확인할 수 없어 판단을 보류합니다. 입력은 서버로 전송하지 않습니다.</p></form></section><section class="verdict-panel" id="verdict" aria-live="polite"><div class="court-seal">⚖</div><span class="eyebrow">COURT IS NOW IN SESSION</span><h2>오늘의 사건을<br>접수해주세요.</h2><p>서로 다른 입장을 함께 살피고<br>가볍게 결론을 내려봅니다.</p><div class="verdict-hint"><b>오늘의 추천 사건</b><a href="#court/cafe">카페 가는 길에 정말 화났는가 →</a></div></section></div><section class="history"><div class="section-head"><h2>나의 판결 기록</h2><button class="text-button" id="clear-history">기록 지우기</button></div><p class="muted">이 브라우저의 최근 12건만 저장합니다.</p><div id="trial-history"></div></section>`;renderHistory();document.getElementById('case-select').addEventListener('change',e=>{const c=caseById(e.target.value);document.getElementById('charge').value=c?.charge||'';document.getElementById('defendant').value=c?.defendant??0;document.getElementById('defense').value=''});document.getElementById('trial-form').addEventListener('submit',e=>{e.preventDefault();runTrial()});document.getElementById('clear-history').addEventListener('click',()=>{trialHistory=[];write('tw-trials',[]);renderHistory();toast('판결 기록을 지웠습니다.')})}
function buildVerdict({caseId,defendant,charge,defense,tone}){const c=caseById(caseId);const reviewed=c&&c.defendant===defendant&&charge.trim()===c.charge&&!defense.trim();return {id:Date.now()+'-'+Math.random().toString(36).slice(2,7),caseId:reviewed?c.id:null,defendant,charge,defense,tone,date:new Date().toISOString(),verdict:reviewed?c.verdict:'판단 보류',facts:reviewed?c.facts:['제출된 내용은 당사자가 입력한 주장입니다.','독립적으로 확인한 사실이나 합의된 자료가 없습니다.'],reason:reviewed?c.reason:'입력된 주장이나 변론의 사실 여부를 확인할 수 없습니다. 한쪽 설명만으로 누군가의 잘못을 확정하지 않고 판단을 보류합니다.',sentence:reviewed?c.sentence:'당사자의 설명을 함께 듣고, 확인한 사실부터 합의하기.'}}
function runTrial(){const charge=document.getElementById('charge').value.trim();if(charge.length<5)return toast('사건 내용을 5자 이상 입력해주세요.');const result=buildVerdict({caseId:document.getElementById('case-select').value,defendant:Number(document.getElementById('defendant').value),charge,defense:document.getElementById('defense').value.trim(),tone:document.querySelector('input[name="tone"]:checked').value});trialHistory=[result,...trialHistory].slice(0,12);const ok=write('tw-trials',trialHistory);showVerdict(result);renderHistory();if(!ok)toast('판결은 표시했지만 브라우저 저장은 사용할 수 없습니다.')}
function showVerdict(r){const el=document.getElementById('verdict');el.classList.add('ready');const c=caseById(r.caseId),v=votes[r.caseId];el.innerHTML=`<div class="verdict-header"><span>개테천 모의재판소</span><span>판결문</span></div><span class="eyebrow">${r.tone==='fun'?'엄숙하게 장난 중입니다':'기록과 주장을 구분합니다'}</span><h2 class="verdict-word">${esc(r.verdict)}</h2><p class="defendant-name">피고인 ${esc(people[r.defendant]?.name||'미상')}</p><div class="verdict-section"><b>사건</b><p>${esc(r.charge)}</p></div>${r.defense?`<div class="verdict-section"><b>제출된 변론</b><p>${esc(r.defense)}</p></div>`:''}<div class="verdict-section"><b>${c?'검토한 요약':'확인 상태'}</b><ul>${r.facts.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div><div class="verdict-section"><b>판결 이유</b><p>${esc(r.reason)}</p></div><div class="sentence"><b>${r.tone==='fun'?'재판장의 한마디':'권고'}</b><p>${esc(r.sentence)}</p></div>${c?`<div class="jury"><b>내 배심원 의견</b><p class="muted">이 브라우저에서만 저장되며 친구들의 투표와 합산되지 않습니다.</p><button class="button ${v==='agree'?'selected':''}" data-vote="${c.id}" data-choice="agree" aria-pressed="${v==='agree'}">동의</button><button class="button ${v==='disagree'?'selected':''}" data-vote="${c.id}" data-choice="disagree" aria-pressed="${v==='disagree'}">다른 생각</button></div>`:''}<div class="verdict-actions"><button class="button" id="copy-verdict">판결문 복사</button><button class="button" id="appeal">변론 추가 · 재심</button></div><small class="muted">저장된 사건별 규칙으로 작성한 오락용 판결이며 실시간 AI 응답이 아닙니다.</small>`;document.getElementById('copy-verdict').addEventListener('click',()=>copy(`${people[r.defendant].name} 모의 재판\n사건: ${r.charge}\n판결: ${r.verdict}\n이유: ${r.reason}\n권고: ${r.sentence}`));document.getElementById('appeal').addEventListener('click',()=>{document.getElementById('case-select').value=r.caseId||'';document.getElementById('defendant').value=r.defendant;document.getElementById('charge').value=r.charge;document.getElementById('defense').value=r.defense||'';document.getElementById('defense').focus();toast('변론을 추가하고 다시 개정해주세요.')});el.querySelectorAll('[data-vote]').forEach(b=>b.addEventListener('click',()=>{votes[b.dataset.vote]=b.dataset.choice;const ok=write('tw-votes',votes);showVerdict(r);toast(ok?'내 배심원 의견을 저장했습니다.':'저장 공간을 사용할 수 없습니다.')}))}
function renderHistory(){document.getElementById('trial-history').innerHTML=trialHistory.length?trialHistory.map(r=>`<button class="history-row" data-history="${esc(r.id)}"><span class="verdict-badge">${esc(r.verdict)}</span><b>${esc(r.charge)}</b><span>${esc(people[r.defendant]?.name||'미상')}</span><time>${new Date(r.date).toLocaleDateString('ko-KR')}</time></button>`).join(''):'<div class="empty">아직 접수한 사건이 없습니다.</div>';document.querySelectorAll('[data-history]').forEach(b=>b.addEventListener('click',()=>{const r=trialHistory.find(r=>r.id===b.dataset.history);if(r){showVerdict(r);document.getElementById('verdict').scrollIntoView({behavior:'smooth',block:'start'})}}))}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('복사했습니다.')}catch{toast('복사를 사용할 수 없습니다. 판결문을 선택해서 복사해주세요.')}}
function museum(){app.innerHTML=`<div class="breadcrumb">개테천위키 / 흑역사 박물관</div><section class="page-intro museum-intro"><span class="eyebrow">THE MUSEUM OF LITTLE MOMENTS</span><h1>잊고 싶지만,<br>웃고 넘어갈 수 있는.</h1><p>누군가를 깎아내리기보다, 서로의 허술한 순간을 전시합니다.</p><span class="notice-pill">편집한 사건 요약 · 채팅 원문 없음</span><span class="museum-stamp" aria-hidden="true">개테천<br>COLLECTION<br>№ 005</span></section><div class="directory-tools"><div class="chips">${['전체','무죄','판단 보류','저장한 전시'].map(t=>`<button class="chip ${museumCategory===t?'active':''}" data-museum-filter="${t}" aria-pressed="${museumCategory===t}">${t}</button>`).join('')}</div><span class="muted">기록을 각색한 가벼운 전시입니다.</span></div><div class="museum-grid" id="museum-grid"></div><aside class="editor-note"><b>별명보다 사람이 먼저.</b><span>과장된 사건명은 오락용 편집입니다. 실제 범죄나 도덕적 잘못을 뜻하지 않습니다.</span></aside>`;renderMuseum()}
function renderMuseum(){const list=wiki.cases.filter(c=>museumCategory==='전체'||museumCategory==='저장한 전시'&&museumSaved.includes(c.id)||museumCategory===c.verdict);document.getElementById('museum-grid').innerHTML=list.length?list.map((c)=>`<article class="museum-card"><div class="museum-visual visual-${c.id}"><span class="exhibit-number">EXHIBIT ${String(wiki.cases.indexOf(c)+1).padStart(3,'0')}</span><span class="exhibit-symbol">${{cafe:'☕',mbti:'ABCD',running:'↝',liverpool:'FC',parking:'P'}[c.id]}</span><span class="exhibit-label">${esc(c.category)}</span></div><div class="museum-copy"><div class="museum-meta">${link(people[c.defendant])}<span>${esc(c.verdict)}</span></div><h2>${esc(c.museum)}</h2><p>${esc(c.caption)}</p><div class="museum-actions"><a href="#court/${c.id}">재판 열기 ↗</a><button class="text-button" data-museum-save="${c.id}" aria-pressed="${museumSaved.includes(c.id)}">${museumSaved.includes(c.id)?'★ 저장됨':'☆ 전시 저장'}</button></div></div></article>`).join(''):'<div class="empty">이 분류의 전시가 없습니다.</div>'}
function pairDetails(a,b){const x=people[a],y=people[b],common=x.tags.filter(t=>y.tags.includes(t)),relations=[...x.relations.filter(r=>r.person===b).map(r=>r.text),...y.relations.filter(r=>r.person===a).map(r=>r.text)];return {x,y,common,relations:[...new Set(relations)]}}
function graph(){const coords=people.map((p,i)=>{const rad=(i*30-90)*Math.PI/180;return {x:360+Math.cos(rad)*245,y:310+Math.sin(rad)*225}});const edges=[];people.forEach(p=>p.relations.forEach(r=>{const key=[p.id,r.person].sort((a,b)=>a-b).join('-');if(!edges.some(e=>e.key===key))edges.push({key,a:p.id,b:r.person})}));return `<svg viewBox="0 0 720 620" class="relationship-svg" role="group" aria-label="12명의 기록상 관계 지도. 인물 노드를 선택하거나 아래 목록에서 두 사람을 고르세요."><defs><pattern id="dots" width="22" height="22" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#dfe7e4"/></pattern></defs><rect width="720" height="620" fill="url(#dots)"/>${edges.map(e=>{const s=coords[e.a],t=coords[e.b],active=[e.a,e.b].includes(mapA),pair=([e.a,e.b].includes(mapA)&&[e.a,e.b].includes(mapB));return `<line x1="${s.x}" y1="${s.y}" x2="${t.x}" y2="${t.y}" class="map-edge ${active?'active':''} ${pair?'pair':''}"/>`}).join('')}<circle cx="360" cy="310" r="57" fill="#fff" stroke="#e3e9e6"/><text x="360" y="306" text-anchor="middle" class="map-center">개테천</text><text x="360" y="326" text-anchor="middle" class="map-center-small">12 PEOPLE</text>${people.map((p,i)=>{const c=coords[i],selected=i===mapA,secondary=i===mapB;return `<g class="map-node ${selected?'active':''} ${secondary?'secondary':''}" data-map-person="${i}" transform="translate(${c.x},${c.y})" tabindex="0" role="button" aria-label="${esc(p.name)} 중심으로 관계 보기" aria-pressed="${selected}"><circle r="29"/><text text-anchor="middle" dy="6" class="node-initial">${esc(p.name.slice(-2))}</text><text text-anchor="middle" y="49" class="node-name">${esc(p.name)}</text></g>`}).join('')}</svg>`}
function mapPage(a,b){if(a!==undefined&&people[Number(a)])mapA=Number(a);if(b!==undefined&&people[Number(b)])mapB=Number(b);if(mapB===mapA)mapB=(mapA+1)%people.length;const d=pairDetails(mapA,mapB);app.innerHTML=`<div class="breadcrumb">개테천위키 / 인간관계 지도</div><section class="map-heading"><div><span class="eyebrow">PEOPLE & CONNECTIONS</span><h1>우리는 어떻게 연결될까.</h1><p>인물을 누르면 연결이 선명해집니다. 두 사람의 공통 관심사도 찾아보세요.</p></div><span class="notice-pill">관계 기록 기준 · 친밀도 점수 없음</span></section><div class="map-layout"><section class="map-panel"><div class="map-legend"><span><i></i> 기록에 등장하는 연결</span><span><i class="selected"></i> 선택한 인물의 연결</span></div>${graph()}<p class="muted map-footnote">선이 없다고 친하지 않다는 뜻은 아닙니다. 노드의 위치와 거리는 친밀도를 나타내지 않습니다.</p></section><aside class="pair-panel panel"><span class="eyebrow">SIDE BY SIDE</span><h2>두 사람 비교</h2><label for="map-a">기준 인물</label><select id="map-a">${options(mapA)}</select><label for="map-b">비교 인물</label><select id="map-b">${options(mapB)}</select><div class="pair-avatars">${avatar(d.x)}<span>×</span>${avatar(d.y)}</div><div class="pair-names">${link(d.x)}<span>·</span>${link(d.y)}</div><h3>공통 관심사</h3><div class="tags">${d.common.length?tags(d.common):'<span class="muted">등록된 공통 태그가 없습니다.</span>'}</div><h3>기록에서 확인한 연결</h3>${d.relations.length?d.relations.map(t=>`<p class="connection-note">${esc(t)}</p>`).join(''):'<p class="muted">이번에 정리한 자료에는 두 사람의 직접 연결이 없습니다.</p>'}<h3>MBTI 기록</h3><div class="mbti-compare"><span>${esc(d.x.name)}<b>${esc(d.x.mbti.title)}</b></span><span>${esc(d.y.name)}<b>${esc(d.y.mbti.title)}</b></span></div><button class="button wide" id="copy-pair">관계 링크 복사</button></aside></div>`;['map-a','map-b'].forEach(id=>document.getElementById(id).addEventListener('change',()=>{let a=Number(document.getElementById('map-a').value),b=Number(document.getElementById('map-b').value);if(a===b){toast('서로 다른 두 사람을 선택해주세요.');document.getElementById(id).value=id==='map-a'?mapA:mapB;return}location.hash=`map/${a}/${b}`}));document.querySelectorAll('[data-map-person]').forEach(n=>{const activate=()=>{const a=Number(n.dataset.mapPerson),b=a===mapB?mapA:mapB;location.hash=`map/${a}/${b}`};n.addEventListener('click',activate);n.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate()}})});document.getElementById('copy-pair').addEventListener('click',()=>copy(location.href.split('#')[0]+`#map/${mapA}/${mapB}`))}
function guide(){app.innerHTML=`<div class="breadcrumb">개테천위키 / 편집 기준</div><section class="page-intro"><span class="eyebrow">EDITORIAL NOTES</span><h1>친구를 기록하는 기준.</h1><p>알고 있는 것과 아직 모르는 것을 구분합니다.</p></section><article class="guide panel"><h2>정보의 범위</h2><p>${wiki.meta.start}~${wiki.meta.end}의 대화 ${num(wiki.meta.total)}건에서 12명의 취향과 관계를 선별했습니다. 모든 메시지의 의미를 빠짐없이 분석한 전기는 아닙니다. 이 사이트의 배포 데이터에는 채팅 원문을 포함하지 않습니다.</p><h2>이름과 나이</h2><p>이름과 대화명은 기존 인물 자료를 따릅니다. 확인된 생년월일은 없어 나이는 미상으로 표시합니다. 프로필에서 입력한 생년월일은 현재 브라우저에만 저장하고 만 나이를 계산합니다.</p><h2>MBTI와 성향</h2><p>MBTI는 당시의 자기표현과 복수 검사 기록입니다. 현재 유형이나 심리 상태를 진단하지 않습니다. 성향은 취미와 대화 참여 방식을 편집한 설명입니다.</p><h2>비슷한 인물과 관계 지도</h2><p>비슷한 인물은 공통 취미 태그 하나당 3점, 기록상 관계가 있으면 1점을 더해 정렬합니다. 성격이나 궁합 점수가 아닙니다. 관계 지도는 기존에 정리된 연결만 표시하고 선의 굵기와 거리에 친밀도 의미를 부여하지 않습니다.</p><h2>AI 재판소와 박물관</h2><p>현재 재판소는 실시간 AI 모델 대신 검토한 5개 사건의 규칙과 판결문을 사용합니다. 새 사건, 변경된 내용, 추가 변론은 진위를 확인할 수 없어 판단 보류로 처리합니다. 장난스러운 분위기를 선택해도 사실 판단은 바뀌지 않습니다. 박물관의 제목은 가벼운 오락용 편집이며 실제 범죄나 잘못을 단정하지 않습니다.</p><h2>저장과 공유</h2><p>북마크, 생년월일, 판결 기록, 배심원 의견은 현재 브라우저에만 저장됩니다. 친구들의 브라우저와 동기화되거나 투표가 합산되지 않습니다. 판결문 복사에는 직접 입력한 사건 내용도 포함되므로 공유 전 내용을 확인하세요. 아바타는 실제 얼굴과 무관한 창작물입니다.</p><button class="button" id="clear-local">이 사이트의 브라우저 저장 데이터 지우기</button><p id="clear-local-status" class="muted" role="status"></p></article>`;document.getElementById('clear-local').addEventListener('click',()=>{['theme-wiki-saved','tw-profiles','tw-trials','tw-votes','tw-museum-saved'].forEach(k=>{try{localStorage.removeItem(k)}catch{}});saved=[];profileEdits={};trialHistory=[];votes={};museumSaved=[];document.getElementById('clear-local-status').textContent='저장된 프로필·북마크·판결·의견을 지웠습니다.'})}
function missing(){app.innerHTML='<div class="empty"><h1>문서를 찾을 수 없습니다.</h1><a class="button" href="#">인물 문서로 돌아가기</a></div>'}
function route(){const [kind,id,b]=location.hash.slice(1).split('/');if(kind==='person'&&/^\d+$/.test(id))person(Number(id));else if(kind==='court')court(id);else if(kind==='museum')museum();else if(kind==='map'||kind==='compare')mapPage(id,b);else if(kind==='guide')guide();else if(!kind)home();else missing();const pageTitle=kind==='person'&&people[id]?people[id].name:({court:'AI 재판소',museum:'흑역사 박물관',map:'인간관계 지도',guide:'편집 기준'})[kind];document.title=(pageTitle?pageTitle+' - ':'')+'개테천위키';document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(kind||'home');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});window.scrollTo(0,0)}
app.addEventListener('click',e=>{const section=e.target.closest('[data-section]');if(section){e.preventDefault();document.getElementById(section.dataset.section)?.scrollIntoView({behavior:'smooth',block:'start'});return}const s=e.target.closest('[data-save]');if(s){const id=Number(s.dataset.save);saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];const ok=write('theme-wiki-saved',saved);if(document.getElementById('cards'))renderCards();else{s.textContent=saved.includes(id)?'★ 저장됨':'☆ 문서 저장';s.setAttribute('aria-pressed',saved.includes(id))}if(!ok)toast('이 브라우저에서는 북마크를 영구 저장할 수 없습니다.')}const f=e.target.closest('[data-filter]');if(f){category=f.dataset.filter;home();document.getElementById('cards').scrollIntoView({block:'nearest'})}const m=e.target.closest('[data-museum-filter]');if(m){museumCategory=m.dataset.museumFilter;museum()}const ms=e.target.closest('[data-museum-save]');if(ms){const id=ms.dataset.museumSave;museumSaved=museumSaved.includes(id)?museumSaved.filter(x=>x!==id):[...museumSaved,id];const ok=write('tw-museum-saved',museumSaved);renderMuseum();if(!ok)toast('이 브라우저에서는 전시를 영구 저장할 수 없습니다.')}});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();app.focus();app.scrollIntoView({block:'start'})});
document.getElementById('random-person').addEventListener('click',()=>{let id=Math.floor(Math.random()*people.length);if(location.hash===`#person/${id}`)id=(id+1)%people.length;location.hash=`person/${id}`});
document.getElementById('side-people').innerHTML=people.map(p=>`<a href="#person/${p.id}"><span class="side-dot"></span>${esc(p.name)}</a>`).join('');
window.addEventListener('hashchange',route);route();
